import { useState } from "react";

export function InlineEdit({
  label = "{{label}}",
  value: initialValue = "{{value}}",
  editing: initialEditing = {{editing}},
  accent = "{{accent}}",
}) {
  const [editing, setEditing] = useState(initialEditing);
  const [value, setValue] = useState(initialValue);
  return (
    <div style={{ width: 280, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <p style={{ margin: "0 0 6px", fontSize: 12, fontWeight: 600, color: "#241430aa" }}>{label}</p>
      {editing ? (
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <input type="text" value={value} onChange={(e) => setValue(e.target.value)} style={{ flex: 1, padding: "8px 10px", borderRadius: 7, border: "1.5px solid " + accent, font: "inherit" }} />
          <button type="button" aria-label="Save" onClick={() => setEditing(false)} style={{ width: 30, height: 30, borderRadius: 7, border: "none", background: accent, cursor: "pointer" }}>&#10003;</button>
          <button type="button" aria-label="Cancel" onClick={() => setEditing(false)} style={{ width: 30, height: 30, borderRadius: 7, border: "none", background: accent, cursor: "pointer" }}>&times;</button>
        </div>
      ) : (
        <button type="button" onClick={() => setEditing(true)} style={{ display: "inline-flex", alignItems: "center", gap: 8, border: "none", background: "transparent", fontWeight: 600, cursor: "pointer", color: "#241430", padding: "4px 0" }}>
          {value} <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={accent} strokeWidth="2" aria-hidden="true"><path d="M16 3l5 5-11 11H5v-5z" /></svg>
        </button>
      )}
    </div>
  );
}
